"""
clothoid.py — 由 (x,y,psi) 离散路径生成近似Clothoid平滑轨迹与速度曲线

功能概述
- 输入：一系列姿态点 [(x_i, y_i, psi_i)]（单位沿用地图，通常为厘米，角度弧度）
- 输出：重采样轨迹（x_s, y_s, psi_s, kappa_s, s），以及速度剖面 v(s)、t(s)

做法要点
- 采用几何微分从离散点估算弧长与曲率，并可做轻量平滑；
- 可选：分段线性曲率近似（简化clothoid），保证曲率变化率有界；
- 基于最大速度、最大加速度/减速度、最大横向加速度 a_lat = v^2 * |kappa| 做速度限制；
- 通过前向/后向两遍传播形成可行速度剖面；

注意
- 若你需要严格的Euler螺线拟合，可替换为开源库（如 PyClothoids）；本实现采用工程近似，轻量且无外部依赖。
"""

from __future__ import annotations

import math
from typing import Iterable, List, Tuple, Optional, Dict

import rclpy.logging


# ------------- 基础几何与工具 -------------

def normalize_angle(th: float) -> float:
	return (th + math.pi) % (2.0 * math.pi) - math.pi


def path_arclength(points: List[Tuple[float, float]]) -> List[float]:
	s = [0.0]
	for i in range(1, len(points)):
		dx = points[i][0] - points[i - 1][0]
		dy = points[i][1] - points[i - 1][1]
		s.append(s[-1] + math.hypot(dx, dy))
	return s


def finite_diff_heading(x: List[float], y: List[float]) -> List[float]:
	n = len(x)
	psi = [0.0] * n
	for i in range(n):
		if i == 0:
			dx = x[i + 1] - x[i]
			dy = y[i + 1] - y[i]
		elif i == n - 1:
			dx = x[i] - x[i - 1]
			dy = y[i] - y[i - 1]
		else:
			dx = x[i + 1] - x[i - 1]
			dy = y[i + 1] - y[i - 1]
		psi[i] = math.atan2(dy, dx)
	return psi


def curvature_from_xy(x: List[float], y: List[float]) -> List[float]:
	n = len(x)
	k = [0.0] * n
	for i in range(1, n - 1):
		x1, y1 = x[i - 1], y[i - 1]
		x2, y2 = x[i], y[i]
		x3, y3 = x[i + 1], y[i + 1]
		a = math.hypot(x2 - x1, y2 - y1)
		b = math.hypot(x3 - x2, y3 - y2)
		c = math.hypot(x3 - x1, y3 - y1)
		denom = max(a * b * c, 1e-9)
		# 使用平面三角形外接圆曲率公式的稳健近似
		num = (x2 - x1) * (y3 - y1) - (y2 - y1) * (x3 - x1)
		k[i] = 2.0 * num / denom
	k[0] = k[1]
	k[-1] = k[-2]
	return k


def moving_average(arr: List[float], win: int) -> List[float]:
	if win <= 1:
		return arr[:]
	n = len(arr)
	out = [0.0] * n
	half = win // 2
	for i in range(n):
		s = 0.0
		c = 0
		for j in range(max(0, i - half), min(n, i + half + 1)):
			s += arr[j]
			c += 1
		out[i] = s / max(1, c)
	return out


def resample_by_s(x: List[float], y: List[float], psi: List[float], step: float) -> Tuple[List[float], List[float], List[float], List[float]]:
	pts = list(zip(x, y))
	s = path_arclength(pts)
	if s[-1] <= 1e-6:
		return x[:], y[:], psi[:], [0.0] * len(x)

	S = [0.0]
	xr = [x[0]]
	yr = [y[0]]
	psir = [psi[0]]
	target = step
	i = 1
	while target < s[-1] and i < len(s):
		while i < len(s) and s[i] < target:
			i += 1
		if i >= len(s):
			break
		# 线性插值
		t = (target - s[i - 1]) / max(s[i] - s[i - 1], 1e-9)
		xr.append(x[i - 1] + t * (x[i] - x[i - 1]))
		yr.append(y[i - 1] + t * (y[i] - y[i - 1]))
		ang = normalize_angle(psi[i - 1])
		ang2 = normalize_angle(psi[i])
		# 球面线性插值近似（小角度）
		dang = normalize_angle(ang2 - ang)
		psir.append(normalize_angle(ang + t * dang))
		S.append(target)
		target += step

	if S[-1] < s[-1]:
		xr.append(x[-1])
		yr.append(y[-1])
		psir.append(psi[-1])
		S.append(s[-1])

	return xr, yr, psir, S


# ------------- 速度曲线生成 -------------

def speed_profile(
	s: List[float],
	kappa: List[float],
	v_max: float = 50.0,
	a_long: float = 50.0,
	a_brake: float = 80.0,
	a_lat_max: float = 200.0,
	r_max: Optional[float] = None,
) -> Tuple[List[float], List[float]]:
	"""
	基于纵向加速度与横向加速度约束生成速度曲线。
	- s: 弧长（单调非减）
	- kappa: 曲率（与 s 对齐）
	- v_max: 速度上限（单位与 s/t 一致，若 s 是 cm，则 v 是 cm/s）
	- a_long: 最大加速度（cm/s^2）
	- a_brake: 最大减速度（正值，cm/s^2）
	- a_lat_max: 最大横向加速度阈值（cm/s^2），约束 v <= sqrt(a_lat_max/|kappa|)
	返回：v(s) 与 t(s)（累计时间）
	"""
	n = len(s)
	v = [0.0] * n
	v_bound = [v_max] * n
	# 横向加速度限制
	for i in range(n):
		if abs(kappa[i]) > 1e-9:
			v_bound[i] = min(v_bound[i], math.sqrt(max(a_lat_max, 0.0) / abs(kappa[i])))
			# 航向角速度上限：|r| = |kappa| * v <= r_max => v <= r_max/|kappa|
			if r_max is not None and r_max > 0:
				v_bound[i] = min(v_bound[i], r_max / max(abs(kappa[i]), 1e-9))

	# 前向传播（加速）
	v[0] = 0.0
	for i in range(1, n):
		ds = max(s[i] - s[i - 1], 1e-9)
		v_pred = math.sqrt(max(v[i - 1] ** 2 + 2.0 * a_long * ds, 0.0))
		v[i] = min(v_pred, v_bound[i])

	# 后向传播（制动到终点或弯道），强制终点速度为0
	v[-1] = 0.0
	for i in range(n - 2, -1, -1):
		ds = max(s[i + 1] - s[i], 1e-9)
		v_brk = math.sqrt(max(v[i + 1] ** 2 + 2.0 * a_brake * ds, 0.0))
		v[i] = min(v[i], v_brk, v_bound[i])

	# 积分得到时间
	t = [0.0] * n
	for i in range(1, n):
		ds = max(s[i] - s[i - 1], 1e-9)
		v_avg = max(1e-6, 0.5 * (v[i] + v[i - 1]))
		t[i] = t[i - 1] + ds / v_avg
	return v, t


# ------------- 主API -------------

def fit_and_speed(
	path: List[Tuple[float, float, float]] | List[Tuple[float, float, float, int]],
	resample_step: float = 2.0,
	smooth_win: int = 5,
	v_max: float = 50.0,
	a_long: float = 50.0,
	a_brake: float = 80.0,
	a_lat_max: float = 200.0,
	r_max: Optional[float] = None,
	kappa_max: Optional[float] = None,
	directions: Optional[List[int]] = None,
	enforce_zero_at_switch: bool = True,
	auto_infer_if_constant: bool = True,
) -> Dict[str, List[float]]:
	"""
	从 (x,y,psi) 序列生成重采样轨迹与速度曲线。
	返回：{
	  'x','y','psi','s','kappa','v','t'
	}
	说明：单位沿用输入（通常cm、rad）。
	额外约束：
	- r_max：艏摇角速度上限（rad/s），通过 v<=r_max/|kappa| 施加；
	- kappa_max：曲率幅值上限（1/长度），用于抑制离散几何噪声并体现最小转弯半径。
	"""
	if not path or len(path) < 3:
		return {
			'x': [p[0] for p in path],
			'y': [p[1] for p in path],
			'psi': [p[2] for p in path],
			's': [0.0] * len(path),
			'kappa': [0.0] * len(path),
			'v': [0.0] * len(path),
			't': [0.0] * len(path),
		}

	# ----- 方向处理 -----
	# 1) 初步解包：若输入自带方向则读取，否则全设为 +1
	if directions is None:
		if len(path[0]) == 4:  # type: ignore[index]
			directions = [int(p[3]) for p in path]  # type: ignore[index]
		else:
			directions = [1] * len(path)
	# 归一化符号（0 视为 +1）
	directions = [1 if d >= 0 else -1 for d in directions]

	# 2) 若全部同号且允许自动推断，则尝试基于几何推断前/后段
	if auto_infer_if_constant and len(path) >= 3:
		inferred = infer_path_directions([(p[0], p[1], p[2]) for p in path])

		directions = inferred
        # # 仅当推断结果包含双向时才替换
		# if any(d != inferred[0] for d in inferred):
		# 	directions = inferred

	x = [p[0] for p in path]
	y = [p[1] for p in path]
	psi = [normalize_angle(p[2]) for p in path]

	# 重采样（保证均匀弧长间隔）
	xr, yr, psir, sr = resample_by_s(x, y, psi, resample_step)

	# 曲率估计并平滑
	kappa = curvature_from_xy(xr, yr)
	if smooth_win > 1:
		kappa = moving_average(kappa, smooth_win)
	# 可选：限制曲率幅值（体现 R_min = 1/kappa_max）
	if kappa_max is not None and kappa_max > 0:
		km = float(kappa_max)
		kappa = [max(-km, min(km, kv)) for kv in kappa]

	v_mag, t = speed_profile(sr, kappa, v_max=v_max, a_long=a_long, a_brake=a_brake, a_lat_max=a_lat_max, r_max=r_max)

	# 重采样方向：简单最近邻（基于弧长索引比例）
	path_s = path_arclength(list(zip(x, y)))
	# 避免 length mismatch
	if path_s[-1] < 1e-6:
		res_dirs = [1] * len(v_mag)
	else:
		res_dirs: List[int] = []
		for s_val in sr:
			ratio = s_val / max(1e-9, path_s[-1])
			idx = min(len(path_s) - 1, int(round(ratio * (len(path_s) - 1))))
			res_dirs.append(directions[idx])

	# 在方向切换处可选强制速度为 0（形成换向停顿）
	if enforce_zero_at_switch and len(v_mag) > 1:
		for i in range(1, len(res_dirs)):
			if res_dirs[i] != res_dirs[i - 1]:
				v_mag[i] = 0.0
				# 为保证加减速一致性，可将前一元素也置 0（避免大跳变）
				v_mag[i - 1] = 0.0

	# 施加符号
	v_signed = [res_dirs[i] * v_mag[i] for i in range(len(v_mag))]

	# 纵向/横向/艏摇角速度（简化：无侧滑，v_lat=0，r = kappa * u）
	u_body = v_signed
	v_lat = [0.0 for _ in v_signed]
	r = [kappa[i] * u_body[i] for i in range(len(u_body))]

	return {
		'x': xr,
		'y': yr,
		'psi': psir,
		's': sr,
		'kappa': kappa,
		'v': v_mag,  # 无符号速度
		'u': u_body,  # 有符号纵向速度
		'v_lat': v_lat,
		'r': r,
		't': t,
		'dir': res_dirs,
	}


# ------------- 方向推断辅助 -------------
def infer_path_directions(path_xyz: List[Tuple[float, float, float]], yaw_threshold: float = math.radians(90)) -> List[int]:
    """根据位移与姿态朝向点积推断前进/倒车。
    原理:
      - dot = 位移向量·朝向向量 = |位移| * cos(夹角)
      - dot > 0: 前进(夹角 < 90°)
      - dot < 0: 倒车(夹角 > 90°)
      
    参数:
      yaw_threshold: 判定倒车的最小夹角阈值(默认90°,可适当放宽到120°以容忍小偏差)
    """
    
    logger = rclpy.logging.get_logger('clothoid')
    logger.set_level(rclpy.logging.LoggingSeverity.DEBUG)
    n = len(path_xyz)
    if n == 0:
        return []
    if n == 1:
        return [1]
    
    dirs_seg: List[int] = []
    for i in range(n - 1):
        x1, y1, psi1 = path_xyz[i]
        x2, y2, _ = path_xyz[i + 1]
        dx, dy = x2 - x1, y2 - y1
        dist = math.hypot(dx, dy)
        
        if dist < 1e-6:
            # 重合点,继承前一段方向
            dirs_seg.append(dirs_seg[-1] if dirs_seg else 1)
            continue
        
        # 船头朝向单位向量
        hx, hy = math.cos(psi1), math.sin(psi1)
        
        # 位移与朝向的点积
        dot = dx * hx + dy * hy
        
        # ✓ 修正判定逻辑
        if dot < 0:
            # 位移与朝向反向(夹角 > 90°) → 倒车
            ang = math.acos(max(-1.0, min(1.0, dot / dist)))
            
            if ang >= yaw_threshold:
                dirs_seg.append(-1)
            else:
                # 如果夹角接近90°但小于阈值,保守判定为前进(避免误判)
                dirs_seg.append(1 if ang < math.radians(100) else -1)
                
            logger.debug(f"Clothoid Debug: Point {i} to {i+1}, dot={dot:.3f}, dist={dist:.3f}, ang(deg)={math.degrees(ang):.2f}, dir={dirs_seg[-1]}")
        else:
            # 位移与朝向同向(夹角 < 90°) → 前进
            dirs_seg.append(1)
    
    # 生成点级别符号(长度 n):首点取第一段,末点取最后一段
    dirs_pts = [dirs_seg[0]] + dirs_seg + [dirs_seg[-1]]
    
    # 去除孤立翻转:模式 (+1,-1,+1) 或 (-1,+1,-1)
    for i in range(1, n - 1):
        if dirs_pts[i - 1] == dirs_pts[i + 1] != dirs_pts[i]:
            dirs_pts[i] = dirs_pts[i - 1]
    
    return dirs_pts


def pack_points_with_velocity(res: Dict[str, List[float]]) -> List[Tuple[float, float, float, float, float, float]]:
	"""
	将 fit_and_speed 的结果打包为点序列 (x, y, psi, u, v, r)
	- 其中 u 为纵向速度（等于 res['v']），v 为横向速度（此处为0），r 为艏摇角速度。
	"""
	x = res.get('x', [])
	y = res.get('y', [])
	psi = res.get('psi', [])
	u = res.get('u', res.get('v', []))
	v_lat = res.get('v_lat', [0.0] * len(u))
	r = res.get('r', [])
	t = res.get('t', [])
	out: List[Tuple[float, float, float, float, float, float, float]] = []
	for i in range(min(len(x), len(y), len(psi), len(u), len(v_lat), len(r), len(t))):
		out.append((x[i], y[i], psi[i], u[i], v_lat[i], r[i], t[i]))
	return out

def resample_uniform_time(res: Dict[str, List[float]], dt: float) -> Dict[str, List[float]]:
    """
    将 fit_and_speed 的输出按固定时间间隔 dt 重采样。
    输入:
      res: fit_and_speed 的返回字典（必须包含键 't'）
      dt : 目标固定时间步（秒；单位需与 res['t'] 一致）
    返回:
      新的结果字典，仅包含对齐到均匀时间网格的列（包含 't'）
    """
    import numpy as np

    t = np.asarray(res.get('t', []), dtype=float)
    if t.size == 0 or t[-1] <= 1e-9:
        return {'t': []}

    ts = np.arange(0.0, float(t[-1]) + 1e-9, float(dt))

    out: Dict[str, List[float]] = {'t': ts.tolist()}

    # 这些量与 t 同长度，允许按时间插值
    interp_keys = ['x', 'y', 'psi', 'u', 'v_lat', 'r', 's', 'kappa']
    for k in interp_keys:
        arr = res.get(k, None)
        if arr is not None and len(arr) == len(t):
            arr_np = np.asarray(arr, dtype=float)
            out[k] = np.interp(ts, t, arr_np).tolist()

    return out


def pretty_print_points_table(pts: List[Tuple[float, float, float, float, float, float, float]]) -> None:
	"""
	以对齐表格的方式打印 (x, y, psi, u, v_lat, r, t) 列，提升可读性。
	"""
	if not pts:
		print('(no points)')
		return
	# 表头
	header = f"{'i':>4} {'x':>10} {'y':>10} {'psi':>10} {'u':>10} {'v_lat':>10} {'r':>10} {'t':>10}"
	print(header)
	print('-' * len(header))
	for i, (x, y, psi, u, v_lat, r, t) in enumerate(pts):
		print(f"{i:4d} {x:10.3f} {y:10.3f} {psi:10.3f} {u:10.3f} {v_lat:10.3f} {r:10.3f} {t:10.3f}")


def save_csv(res: Dict[str, List[float]], out_path: str) -> None:
	"""
	保存完整结果为 CSV：列为 x,y,psi,s,kappa,u,v_lat,r,t
	"""
	try:
		import csv, os
		os.makedirs(os.path.dirname(out_path) or '.', exist_ok=True)
		keys = ['x', 'y', 'psi', 's', 'kappa', 'u', 'v_lat', 'r', 't']
		n = min(len(res.get('x', [])), len(res.get('y', [])), len(res.get('psi', [])))
		n = min(n, *(len(res.get(k, [])) for k in ['s', 'kappa', 'u', 'v_lat', 'r', 't'])) if n > 0 else 0
		with open(out_path, 'w', newline='') as f:
			writer = csv.writer(f)
			writer.writerow(keys)
			for i in range(n):
				writer.writerow([res[k][i] for k in keys])
	except Exception as e:
		print('CSV save failed:', e)


